import{_ as d,c as o,o as t,b2 as c}from"./chunks/framework.CUhoHPxN.js";const u=JSON.parse('{"title":"角色管理设计文档","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-05-14-role-management-design.md","filePath":"superpowers/specs/2026-05-14-role-management-design.md"}'),r={name:"superpowers/specs/2026-05-14-role-management-design.md"};function a(l,e,s,i,n,h){return t(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="角色管理设计文档" tabindex="-1">角色管理设计文档 <a class="header-anchor vp-link" href="#角色管理设计文档" aria-label="Permalink to &quot;角色管理设计文档&quot;">​</a></h1><h2 id="_1-背景与目标" tabindex="-1">1. 背景与目标 <a class="header-anchor vp-link" href="#_1-背景与目标" aria-label="Permalink to &quot;1. 背景与目标&quot;">​</a></h2><p>在系统管理域内实现「角色」全生命周期与授权：分页查询与筛选、列表展示、状态切换（需确认）、新增/编辑、菜单权限（树形勾选，全选/全不选/父子联动）、数据权限（若依式范围 + 自定义部门）、单条与批量删除、分配用户（已分配/未分配流转）、导出角色列表。</p><p>原始需求见 <code>原始需求/系统管理/角色管理-需求文档.md</code>。本文档为经 <code>/brainstorming</code> 澄清后的<strong>定稿设计</strong>；与原始需求不一致处（尤其 HTTP 方法、用户表缺失前提下的落地方式）以本文为准。</p><h2 id="_2-需求澄清结论-已确认" tabindex="-1">2. 需求澄清结论（已确认） <a class="header-anchor vp-link" href="#_2-需求澄清结论-已确认" aria-label="Permalink to &quot;2. 需求澄清结论（已确认）&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>序号</th><th>结论</th></tr></thead><tbody><tr><td>1</td><td>写操作统一使用 <strong><code>POST</code></strong> 表达新增、修改、删除、改状态、数据权限、菜单保存、用户授权变更、导出；<strong>读操作</strong>使用 <strong><code>GET</code></strong>（与 <code>AGENTS.md</code> 一致，不对齐原始需求中的 <code>PUT</code>/<code>DELETE</code>）。</td></tr><tr><td>2</td><td>数据权限采用<strong>若依式枚举</strong> + <strong><code>sys_role_dept</code></strong> 存储自定义部门；非自定义范围时清空该角色的部门关联行。枚举取值见 §4.2。</td></tr><tr><td>3</td><td><strong>分配用户</strong>：角色侧提供已分配/未分配分页与批量授权/取消接口；用户主数据来自用户域；本迭代需具备 <strong><code>sys_user</code> 最小表</strong>及分页查询以支撑验收（若与用户管理变更合并建表则单次迁移、避免重复）。</td></tr><tr><td>4</td><td>导出为 <strong><code>xlsx</code></strong>，使用 <code>quickboot-common</code> 既有 Excel 能力，与项目内其他导出风格一致。</td></tr><tr><td>5</td><td>前端在 <strong><code>quick-ui</code></strong> 新建页面，视觉与交互遵循仓库根目录 <strong><code>DESIGN.md</code></strong>；业务交互可参考 <code>原始需求/quick-ui/src/views/system/role/</code>。</td></tr><tr><td>6</td><td><strong>内置超级管理员角色</strong>（种子 <code>role_id = 1</code>）：<strong>禁止删除</strong>；<strong>禁止修改其菜单权限与数据权限</strong>（名称、排序、状态等非权限字段不在此硬限制内，与澄清阶段默认一致）。</td></tr></tbody></table></div><h2 id="_3-范围与非范围" tabindex="-1">3. 范围与非范围 <a class="header-anchor vp-link" href="#_3-范围与非范围" aria-label="Permalink to &quot;3. 范围与非范围&quot;">​</a></h2><h3 id="_3-1-实施范围" tabindex="-1">3.1 实施范围 <a class="header-anchor vp-link" href="#_3-1-实施范围" aria-label="Permalink to &quot;3.1 实施范围&quot;">​</a></h3><ul><li>后端：扩展 <code>sys_role</code>、新增 <code>sys_role_dept</code>、Flyway 迁移；<code>sys_user</code> 最小表及查询（若尚不存在）；<code>io.github.genkidoudou.web.system.role</code>（或与 <code>dept</code>/<code>config</code> 并列命名习惯）下的 Controller / Service / Mapper / domain / dto（Bo、QueryBo、Vo、Excel 行对象）。</li><li>与 <strong><code>sys_role_menu</code></strong>、<strong><code>sys_user_role</code></strong> 的读写衔接；复用 <strong><code>MenuService</code></strong> 已有「角色菜单树 + 已勾选 menuId」读能力；菜单勾选结果保存由角色域事务写入 <code>sys_role_menu</code>（通过调用现有菜单侧能力或共享 Mapper，避免循环依赖：<strong>RoleService → MenuService</strong> 单向）。</li><li>权限标识与原始需求 §6 一致：<code>system:role:list</code>、<code>add</code>、<code>edit</code>、<code>remove</code>、<code>export</code>、<code>dataScope</code>；鉴权与前端 <code>v-hasPermi</code> 对齐。</li><li>前端：路由、菜单、API 模块、列表页、表单抽屉/弹窗、菜单树、数据权限弹窗、分配用户子页或抽屉、导出。</li></ul><h3 id="_3-2-明确不做" tabindex="-1">3.2 明确不做 <a class="header-anchor vp-link" href="#_3-2-明确不做" aria-label="Permalink to &quot;3.2 明确不做&quot;">​</a></h3><ul><li>行级数据权限在 SQL 中的自动拼接切面（若项目已有 DataScope 切面可后续衔接；本文仅定义<strong>角色上配置的范围与部门</strong>持久化与维护 UI）。</li><li>角色复制、角色分级继承、多租户隔离。</li><li>与原始需求文档 §7 <strong>路径与方法字面一致</strong>的 <code>PUT</code>/<code>DELETE</code> 对外契约（以本文 §5 为准）。</li></ul><h2 id="_4-数据模型" tabindex="-1">4. 数据模型 <a class="header-anchor vp-link" href="#_4-数据模型" aria-label="Permalink to &quot;4. 数据模型&quot;">​</a></h2><h3 id="_4-1-表-sys-role-扩展" tabindex="-1">4.1 表 <code>sys_role</code>（扩展） <a class="header-anchor vp-link" href="#_4-1-表-sys-role-扩展" aria-label="Permalink to &quot;4.1 表 `sys_role`（扩展）&quot;">​</a></h3><p>在现有 <code>V5__sys_menu.sql</code> 已建表基础上，由新迁移追加字段：</p><div class="vp-table"><table><thead><tr><th>字段</th><th>类型（建议）</th><th>说明</th></tr></thead><tbody><tr><td><code>data_scope</code></td><td>CHAR(1) NOT NULL DEFAULT &#39;1&#39;</td><td>数据权限范围，取值见 §4.2</td></tr></tbody></table></div><p>其余字段保持与现有一致：<code>role_id</code>、<code>role_name</code>、<code>role_key</code>、<code>role_sort</code>、<code>status</code>、<code>remark</code>、<code>del_flag</code>、审计字段等；<code>role_key</code> 唯一索引已存在。</p><h3 id="_4-2-数据权限枚举-data-scope" tabindex="-1">4.2 数据权限枚举 <code>data_scope</code> <a class="header-anchor vp-link" href="#_4-2-数据权限枚举-data-scope" aria-label="Permalink to &quot;4.2 数据权限枚举 `data_scope`&quot;">​</a></h3><div class="vp-table"><table><thead><tr><th>值</th><th>含义</th></tr></thead><tbody><tr><td><code>1</code></td><td>全部数据权限</td></tr><tr><td><code>2</code></td><td>自定义（依赖 <code>sys_role_dept</code>）</td></tr><tr><td><code>3</code></td><td>本部门</td></tr><tr><td><code>4</code></td><td>本部门及以下</td></tr><tr><td><code>5</code></td><td>仅本人</td></tr></tbody></table></div><p>当 <code>data_scope != &#39;2&#39;</code> 时，服务端应删除该 <code>role_id</code> 在 <code>sys_role_dept</code> 中的全部行，避免脏数据。</p><h3 id="_4-3-表-sys-role-dept-新建" tabindex="-1">4.3 表 <code>sys_role_dept</code>（新建） <a class="header-anchor vp-link" href="#_4-3-表-sys-role-dept-新建" aria-label="Permalink to &quot;4.3 表 `sys_role_dept`（新建）&quot;">​</a></h3><div class="vp-table"><table><thead><tr><th>字段</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>role_id</code></td><td>BIGINT NOT NULL</td><td>FK 逻辑关联 <code>sys_role.role_id</code></td></tr><tr><td><code>dept_id</code></td><td>BIGINT NOT NULL</td><td>逻辑关联 <code>sys_dept.dept_id</code></td></tr></tbody></table></div><p>主键：<code>(role_id, dept_id)</code>。仅当 <code>data_scope = &#39;2&#39;</code> 时维护；保存数据权限时采用<strong>先删后插</strong>或等价事务策略。</p><h3 id="_4-4-表-sys-user-本迭代最小集" tabindex="-1">4.4 表 <code>sys_user</code>（本迭代最小集） <a class="header-anchor vp-link" href="#_4-4-表-sys-user-本迭代最小集" aria-label="Permalink to &quot;4.4 表 `sys_user`（本迭代最小集）&quot;">​</a></h3><p>若仓库尚无 Flyway 定义的 <code>sys_user</code>，本变更新增最小表以支撑「分配用户」列表与关联，字段建议至少包含：</p><ul><li><code>user_id</code>（PK）、登录账号、用户昵称、部门 id（可空）、状态、<code>del_flag</code>、审计字段。</li></ul><p>具体列名与类型与项目既有用户管理规范（<code>sdd/数据库设计规范.md</code>）对齐；若用户管理模块已提供同表，则<strong>不重复建表</strong>，仅引用。</p><h3 id="_4-5-既有表" tabindex="-1">4.5 既有表 <a class="header-anchor vp-link" href="#_4-5-既有表" aria-label="Permalink to &quot;4.5 既有表&quot;">​</a></h3><ul><li><strong><code>sys_role_menu</code></strong>：角色与菜单多对多；菜单保存接口全量替换该角色的关联行（或差异更新，实现阶段选一种并保证幂等与性能可接受）。</li><li><strong><code>sys_user_role</code></strong>：用户与角色多对多；分配用户接口维护此表。</li></ul><h2 id="_5-接口契约" tabindex="-1">5. 接口契约 <a class="header-anchor vp-link" href="#_5-接口契约" aria-label="Permalink to &quot;5. 接口契约&quot;">​</a></h2><p>统一响应 <code>R</code>；分页列表使用 <code>PageInfo&lt;T&gt;</code>（与 <code>SysConfigController</code>、通知公告等一致），Query 参数包含 <code>pageNum</code>、<code>pageSize</code> 及筛选字段。</p><div class="vp-table"><table><thead><tr><th>能力</th><th>方法</th><th>路径</th><th>说明</th></tr></thead><tbody><tr><td>分页列表</td><td>GET</td><td><code>/system/role/list</code></td><td>Query：角色名称、权限字符（<code>role_key</code>）、状态、创建时间区间；返回 <code>R&lt;PageInfo&lt;SysRoleVo&gt;&gt;</code></td></tr><tr><td>详情</td><td>GET</td><td><code>/system/role/{roleId}</code></td><td>含菜单 id 列表或独立菜单树接口回显（与前端约定二选一：详情中带 <code>menuIds</code> <strong>或</strong> 仅依赖菜单树 GET）</td></tr><tr><td>新增</td><td>POST</td><td><code>/system/role/create</code></td><td>Body：Bo；校验分组 Add；<code>role_key</code> 唯一（与 <code>SysConfigController</code> 子路径风格一致）</td></tr><tr><td>修改</td><td>POST</td><td><code>/system/role/update</code></td><td>Body：Bo，含 <code>roleId</code>；分组 Update</td></tr><tr><td>删除</td><td>POST</td><td><code>/system/role/remove</code></td><td>Body：<code>roleId</code> 列表；拦截 <code>role_id=1</code></td></tr><tr><td>状态</td><td>POST</td><td><code>/system/role/changeStatus</code></td><td>Body：<code>roleId</code>、<code>status</code>；若需拦截内置角色则与产品一致（默认允许改状态，仅禁删与禁改菜单/数据权限）</td></tr><tr><td>数据权限</td><td>POST</td><td><code>/system/role/dataScope</code></td><td>Body：<code>roleId</code>、<code>dataScope</code>、可选 <code>deptIds</code>；<code>role_id=1</code> 拒绝</td></tr><tr><td>菜单保存</td><td>POST</td><td><code>/system/role/menu</code></td><td>Body：<code>roleId</code>、<code>menuIds</code>；<code>role_id=1</code> 拒绝</td></tr><tr><td>角色菜单树（读）</td><td>GET</td><td><code>/system/menu/roleMenuTreeselect/{roleId}</code></td><td>返回 <code>RoleMenuTreeselectVo</code>：全量树 + <code>checkedKeys</code>（<code>SysMenuController</code> 已实现）</td></tr><tr><td>已分配用户</td><td>GET</td><td><code>/system/role/authUser/allocatedList</code></td><td>Query：<code>roleId</code>、用户筛选、分页</td></tr><tr><td>未分配用户</td><td>GET</td><td><code>/system/role/authUser/unallocatedList</code></td><td>同上</td></tr><tr><td>批量授权</td><td>POST</td><td><code>/system/role/authUser/selectAll</code></td><td>Body：<code>roleId</code>、用户 id 列表</td></tr><tr><td>取消授权</td><td>POST</td><td><code>/system/role/authUser/cancel</code></td><td>Body：<code>roleId</code>、用户 id</td></tr><tr><td>批量取消</td><td>POST</td><td><code>/system/role/authUser/cancelAll</code></td><td>Body：<code>roleId</code>、用户 id 列表</td></tr><tr><td>导出</td><td>POST</td><td><code>/system/role/export</code></td><td>Query 或 Body 与列表筛选一致；返回文件流</td></tr></tbody></table></div><p>所有 Body 使用 Jakarta Validation；对外 OpenAPI <code>@Tag</code>、<code>@Operation</code>、<code>@Parameter</code> 齐全。</p><h2 id="_6-后端设计" tabindex="-1">6. 后端设计 <a class="header-anchor vp-link" href="#_6-后端设计" aria-label="Permalink to &quot;6. 后端设计&quot;">​</a></h2><h3 id="_6-1-分层与包结构" tabindex="-1">6.1 分层与包结构 <a class="header-anchor vp-link" href="#_6-1-分层与包结构" aria-label="Permalink to &quot;6.1 分层与包结构&quot;">​</a></h3><ul><li>推荐包路径：<code>io.github.genkidoudou.web.system.role</code>（与 <code>system.dept</code>、<code>system.config</code> 等并列）。</li><li>分层：<code>controller</code> / <code>service</code> / <code>service.impl</code> / <code>mapper</code> / <code>domain</code> / <code>dto</code>。</li></ul><h3 id="_6-2-超级管理员规则" tabindex="-1">6.2 超级管理员规则 <a class="header-anchor vp-link" href="#_6-2-超级管理员规则" aria-label="Permalink to &quot;6.2 超级管理员规则&quot;">​</a></h3><ul><li><code>role_id == 1</code>：<strong>不允许</strong> <code>remove</code>；<strong>不允许</strong> <code>dataScope</code>、<code>menu</code> 写接口成功（返回业务异常码，文案清晰）。</li><li>其他写操作是否限制：按 §2 序号 6，<strong>不强制</strong>禁止改名/排序/状态；若后续需收紧，单开变更修订本文档。</li></ul><h3 id="_6-3-业务校验" tabindex="-1">6.3 业务校验 <a class="header-anchor vp-link" href="#_6-3-业务校验" aria-label="Permalink to &quot;6.3 业务校验&quot;">​</a></h3><ul><li><code>role_name</code>、<code>role_key</code>、<code>role_sort</code> 必填；<code>role_key</code> 全局唯一（含逻辑删除语义与项目 <code>del_flag</code> 规则一致）。</li><li>删除前可校验是否仍绑定用户（可选，按产品：强删关联或禁止删；默认建议：<strong>仍绑定用户则禁止删除</strong>并提示）。</li></ul><h3 id="_6-4-异常与日志" tabindex="-1">6.4 异常与日志 <a class="header-anchor vp-link" href="#_6-4-异常与日志" aria-label="Permalink to &quot;6.4 异常与日志&quot;">​</a></h3><ul><li>禁止用 <code>IllegalArgumentException</code> 表达业务失败；使用项目统一业务异常与 <code>ErrorCodes</code>。</li><li>关键写操作记录操作人（审计字段由现有 MetaObjectHandler 填充）。</li></ul><h2 id="_7-前端设计" tabindex="-1">7. 前端设计 <a class="header-anchor vp-link" href="#_7-前端设计" aria-label="Permalink to &quot;7. 前端设计&quot;">​</a></h2><ul><li>路由：<code>/system/role</code>（与 <code>quick-ui</code> 路由表、后台菜单配置一致）。</li><li>列表：查询区（角色名称、<code>role_key</code>、状态、创建时间范围）、<code>C7JsonTable</code> 或项目统一表格组件、状态开关 + 二次确认、操作列（编辑、数据权限、分配用户、删除）。</li><li>新增/编辑：抽屉或对话框；校验与 §6.3 一致。</li><li>菜单权限：Element Plus 树，<code>check-strictly</code> 与父子联动行为与需求「全选/全不选/父子联动」一致（实现时固定一套配置并写入组件注释）。</li><li>数据权限：单选 <code>data_scope</code>；值为自定义时展示部门树多选，提交 <code>deptIds</code>。</li><li>分配用户：内嵌表格双列表 + 批量按钮，调用 §5 分配用户相关接口。</li><li>样式与间距遵循 <code>DESIGN.md</code>（主色 <code>#0a2463</code>、背景 <code>#f5f7fa</code>、高亮 <code>#409eff</code> 等）。</li></ul><h2 id="_8-测试与验收" tabindex="-1">8. 测试与验收 <a class="header-anchor vp-link" href="#_8-测试与验收" aria-label="Permalink to &quot;8. 测试与验收&quot;">​</a></h2><ul><li><strong>权限树</strong>：保存菜单后再次进入，<code>checkedKeys</code> 与树勾选一致。</li><li><strong>数据权限</strong>：切换 <code>data_scope</code> 时 <code>sys_role_dept</code> 与枚举一致；自定义部门保存与回显正确。</li><li><strong>分配用户</strong>：已分配/未分配列表与批量操作后 <code>sys_user_role</code> 一致。</li><li><strong>导出</strong>：文件可打开，列与列表主要字段一致。</li><li><strong>内置角色</strong>：删除与菜单/数据权限修改被拒绝。</li></ul><p>单元测试优先：<code>role_key</code> 唯一、<code>role_id=1</code> 保护、数据权限切换清理自定义部门行；集成测试视 CI 情况选做。</p><h2 id="_9-文档与实现衔接" tabindex="-1">9. 文档与实现衔接 <a class="header-anchor vp-link" href="#_9-文档与实现衔接" aria-label="Permalink to &quot;9. 文档与实现衔接&quot;">​</a></h2><ul><li>实现前须阅读：<code>openspec/project.md</code>、<code>sdd/后端代码规范.md</code>、<code>sdd/前端代码规范.md</code>、<code>sdd/数据库设计规范.md</code>。</li><li>定稿评审通过后，使用 <strong><code>writing-plans</code></strong> 产出实现任务清单；<strong>不在本文档批准前</strong>启动编码。</li></ul><h2 id="_10-修订记录" tabindex="-1">10. 修订记录 <a class="header-anchor vp-link" href="#_10-修订记录" aria-label="Permalink to &quot;10. 修订记录&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>日期</th><th>说明</th></tr></thead><tbody><tr><td>2026-05-14</td><td>初版定稿（头脑风暴澄清与方案 1：独立 role 包）</td></tr></tbody></table></div>',50)])])}const p=d(r,[["render",a]]);export{u as __pageData,p as default};
